import {sections,newFamily,makeText,validateFamily} from './model.mjs';
import {DriveStore} from './drive.mjs';
const $=id=>document.getElementById(id),drive=new DriveStore();
let families=[],current=null,remote=null,dirty=false,busy=false,history=[],tab='care',pending=new Map(),photoURL=null,toastTimer;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function capture(){if(!current)return;history.push(JSON.stringify(current));if(history.length>40)history.shift();$('undoBtn').disabled=false;}
function changed(){const item=families.find(f=>f.id===current?.id);if(item&&!item.remote){item.data=current;item.name=current.name;}dirty=true;$('saveState').textContent=drive.token?'有修改尚未存入 Drive':'尚未存入雲端，關閉畫面會失去未備份的修改';$('familyTitle').textContent=current.name||'未命名家庭';}
function renderList(){const term=$('search').value.trim().toLocaleLowerCase();$('familyList').innerHTML=families.filter(f=>(f.name||'未命名家庭').toLocaleLowerCase().includes(term)).map(f=>`<button class="family ${current?.id===f.id?'active':''}" data-family="${escape(f.id)}"><strong>${escape(f.name||'未命名家庭')}</strong><small>${f.remote?'已存於 Google Drive':'本次畫面中的草稿'}</small></button>`).join('')||'<p class="empty">目前沒有家庭檔案。<br>從新增家庭開始。</p>';}
function allowLeave(){return !dirty||confirm('目前修改尚未儲存。確定離開這份家庭資料？建議先儲存到 Drive 或下載完整備份。');}
async function selectFamily(id){if(busy||!allowLeave())return;const item=families.find(f=>f.id===id);if(!item)return;try{let data;if(item.remote){const loaded=await drive.load(item.remote.id);data=validateFamily(loaded.data);if(typeof loaded.data.outputDraft==='string')data.outputDraft=loaded.data.outputDraft;remote={id:item.remote.id,version:loaded.version,etag:loaded.etag};item.id=data.id;item.name=data.name;}else{data=item.data;remote=null;}openFamily(data);}catch(e){toast(e.message);}}
function openFamily(data){current=data;dirty=false;history=[];tab='care';$('welcome').hidden=true;$('workspace').hidden=false;render();$('saveState').textContent=remote?'已載入 Google Drive 的家庭檔案':'這是草稿，尚未存入 Google Drive';}
function addFamily(demo=false){if(busy||!allowLeave())return;const f=newFamily(demo?'姆姆家（操作範例）':'');if(demo){Object.assign(f.sections.pets[0].values,{names:'姆姆',identity:'白底虎斑',approach:'依孩子步調'});Object.assign(f.sections.food[0].values,{kind:'乾糧',location:'廚房右側下櫃',amount:'三分之一',unit:'杯',time:'每次到府',tool:'飼料桶內的透明量杯',bowls:'客廳食碗',leftover:'移出洗碗後放回',cleanup:'量杯放回飼料桶，櫃門關好'});f.sections.food[0].note='這是虛構操作範例，可自由修改。';}families.push({id:f.id,name:f.name,data:f});remote=null;openFamily(f);changed();renderList();}
function field(label,value,onChange,{long=false,options=null,placeholder=''}={}){const wrap=document.createElement('label');wrap.className='field'+(long?' note':'');const head=document.createElement('span');head.className='fieldhead';const text=document.createElement('span');text.textContent=label;head.append(text);const clear=document.createElement('button');clear.type='button';clear.className='clear';clear.textContent='清除';clear.setAttribute('aria-label',`清除${label}`);head.append(clear);wrap.append(head);let input;
 if(options){input=document.createElement('select');for(const option of ['',...new Set([...options,...(value&&!options.includes(value)?[value]:[])])]){const o=document.createElement('option');o.value=option;o.textContent=option||'尚未填寫';input.append(o);}const other=document.createElement('input');other.placeholder='其他，直接輸入';other.setAttribute('aria-label',`${label}自訂文字`);other.hidden=true;const custom=document.createElement('option');custom.value='__custom__';custom.textContent='其他，自行填寫';input.append(custom);input.value=value||'';input.addEventListener('change',()=>{if(input.value==='__custom__'){other.hidden=false;other.value='';other.focus();onChange('');}else{other.hidden=true;onChange(input.value);}});other.addEventListener('input',()=>onChange(other.value));wrap.append(input,other);clear.addEventListener('click',e=>{e.preventDefault();input.value='';other.value='';other.hidden=true;onChange('');});
 }else{input=document.createElement(long?'textarea':'input');input.value=value||'';input.placeholder=placeholder;input.addEventListener('input',()=>onChange(input.value));wrap.append(input);clear.addEventListener('click',e=>{e.preventDefault();input.value='';onChange('');input.focus();});}
 input.setAttribute('aria-label',label);return wrap;
}
function changeValue(s,index,key,value){capture();current.sections[s.id][index].values[key]=value;changed();}
function render(){renderList();$('familyTitle').textContent=current.name||'未命名家庭';$('undoBtn').disabled=!history.length;$('nameField').replaceChildren(field('家庭名稱',current.name,value=>{capture();current.name=value;changed();const item=families.find(f=>f.id===current.id);if(item){item.name=value;item.data=current;}renderList();}));$('sectionNav').innerHTML=sections.map(s=>`<a href="#${s.id}">${escape(s.title)}</a>`).join('');const form=$('form');form.replaceChildren();
 for(const s of sections){const details=document.createElement('details');details.id=s.id;details.open=['pets','food'].includes(s.id);const summary=document.createElement('summary');summary.textContent=s.title;details.append(summary);const body=document.createElement('div');body.className='sectionbody';if(s.hint){const p=document.createElement('p');p.className='hint';p.textContent=s.hint;body.append(p);}current.sections[s.id].forEach((row,i)=>{const entry=document.createElement('div');entry.className='entry';if(s.repeat){const head=document.createElement('div');head.className='entryhead';const title=document.createElement('strong');title.textContent=`第 ${i+1} 組`;const remove=document.createElement('button');remove.type='button';remove.textContent='刪除這組';remove.addEventListener('click',()=>{if(!confirm(`刪除「${s.title}」第 ${i+1} 組？可使用復原上一步還原。`))return;capture();current.sections[s.id].splice(i,1);changed();const opened=[...document.querySelectorAll('details[open]')].map(x=>x.id);render();opened.forEach(id=>$(id).open=true);});head.append(title,remove);entry.append(head);}const fields=document.createElement('div');fields.className='fields';for(const [key,label,type,options] of s.fields)fields.append(field(label,row.values[key],value=>changeValue(s,i,key,value),{options:type==='select'?options:null}));entry.append(fields);entry.append(field(s.note,row.note,value=>{capture();row.note=value;changed();},{long:true}));body.append(entry);});if(s.repeat){const add=document.createElement('button');add.className='addrow';add.textContent='新增一組';add.addEventListener('click',()=>{capture();current.sections[s.id].push({values:{},note:''});changed();const opened=[...document.querySelectorAll('details[open]')].map(x=>x.id);render();[s.id,...opened].forEach(id=>$(id).open=true);});body.append(add);}details.append(body);form.append(details);}
 renderPhotos();setTab(tab,false);
}
function setTab(next,announce=true){tab=next;for(const t of ['care','photos','text']){$(t+'Panel').hidden=t!==next;document.querySelector(`[data-tab="${t}"]`).classList.toggle('active',t===next);}if(next==='text'){$('output').value=current.outputDraft??makeText(current);if(announce&&current.outputDraft!==undefined)toast('顯示上次編輯的輸出文字；需要套用照護欄位最新修改時，請按「重新產生」。');}}
function renderPhotos(){const grid=$('photoGrid');grid.replaceChildren();$('photoCount').textContent=current.photos.length;if(!current.photos.length){const p=document.createElement('p');p.className='empty';p.textContent='還沒有照片。可一次選多張，加入後再慢慢補說明。';grid.append(p);}for(const p of current.photos){const card=document.createElement('article');card.className='photocard';const open=document.createElement('button');open.setAttribute('aria-label',`放大照片 ${p.caption||p.name}`);const img=document.createElement('img');img.src=p.thumb;img.alt=p.caption||p.name;img.loading='lazy';open.append(img);open.addEventListener('click',()=>showPhoto(p));card.append(open);card.append(field('照片說明（可留白）',p.caption,value=>{capture();p.caption=value;changed();},{long:true}));const small=document.createElement('small');small.textContent=`原檔 ${(p.size/1024/1024).toFixed(1)} MB`;card.append(small);const remove=document.createElement('button');remove.className='remove';remove.textContent='移除此照片';remove.addEventListener('click',()=>{capture();current.photos=current.photos.filter(x=>x.id!==p.id);changed();renderPhotos();toast('照片已從家庭檔案移除，可復原。Drive 原檔保留，不會永久刪除。');});card.append(remove);grid.append(card);}}
async function photoBlob(p){if(pending.has(p.id))return pending.get(p.id);if(p.driveId)return drive.photo(p.driveId);throw Error('找不到這張照片原檔，請從完整備份還原。');}
async function showPhoto(p){try{const blob=await photoBlob(p);if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(blob);$('fullPhoto').src=photoURL;$('fullPhoto').alt=p.caption||p.name;$('photoCaption').textContent=p.caption;$('lightbox').showModal();}catch(e){toast(e.message);}}
async function thumb(blob){const url=URL.createObjectURL(blob);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('無法讀取這張照片，請使用 JPG、PNG 或 WebP。'));image.src=url;});const scale=Math.min(1,400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.72);}finally{URL.revokeObjectURL(url);}}
async function addPhotos(files){if(!current||busy)return;setBusy(true);let added=0;try{capture();for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('目前支援 JPG、PNG、WebP 照片。');if(f.size>40*1024*1024)throw Error('單張照片超過 40 MB，請先轉存為一般照片。');const p={id:crypto.randomUUID(),name:f.name,caption:'',mime:f.type,size:f.size,thumb:await thumb(f)};pending.set(p.id,f);current.photos.push(p);added++;changed();} }catch(e){toast(e.message);}finally{setBusy(false);renderPhotos();$('photoFiles').value='';if(added)toast(`已加入 ${added} 張照片，請儲存到 Drive。`);}}
function setBusy(value){busy=value;document.querySelectorAll('#workspace input,#workspace select,#workspace textarea,#workspace button,#workspace summary,#workspace .button,#newBtn,#startBtn,#demoBtn,#connectBtn,#restoreBtn,#settingsBtn,#search').forEach(el=>{if(el.tagName==='SUMMARY')el.style.pointerEvents=value?'none':'';else el.disabled=value;});$('undoBtn').disabled=value||!history.length;}
async function connect(){if(busy)return;const clientId=localStorage.getItem('liliOAuthClientId');if(!clientId){$('settings').showModal();return;}if(!allowLeave())return;setBusy(true);try{await drive.connect(clientId);const files=await drive.families();const drafts=families.filter(f=>!f.remote);families=[...drafts,...files.map(f=>({id:f.id,name:f.name.replace(/＿照護資料\.json$/,''),remote:{id:f.id,version:f.version}}))];$('cloudStatus').textContent='已連接保姆 Google Drive';$('cloudHint').textContent='家庭資料與照片保存於你的私人 App 資料夾。請另外下載完整備份。';$('connectBtn').textContent='重新連接／更新家庭清單';renderList();toast('Google Drive 已連接。');}catch(e){toast(e.message);}finally{setBusy(false);}}
async function save(){if(busy||!current)return;if(!drive.token){toast('請先連接 Google Drive。未連線時可下載完整備份，避免遺失。');return;}if(!current.name.trim()){toast('請先填寫家庭名稱。');return;}setBusy(true);try{const copy=structuredClone(current);for(const p of copy.photos){if(!p.driveId){$('saveState').textContent=`正在上傳照片：${p.name}`;const uploaded=await drive.upload(p.name,await photoBlob(p),'photo-v1',copy.id);p.driveId=uploaded.id;const live=current.photos.find(x=>x.id===p.id);live.driveId=p.driveId;}}
 copy.updatedAt=new Date().toISOString();$('saveState').textContent='正在儲存家庭資料…';const result=await drive.save(copy,remote);const readback=await drive.load(result.id);const verified=validateFamily(readback.data);if(verified.id!==copy.id||verified.updatedAt!==copy.updatedAt)throw Error('雲端讀回核對未完成，請保留目前畫面並下載備份。');Object.assign(current,copy);remote={id:result.id,version:readback.version,etag:readback.etag};let item=families.find(f=>f.id===current.id||f.remote?.id===result.id);if(!item){item={};families.push(item);}Object.assign(item,{id:current.id,name:current.name,remote:{...remote}});dirty=false;$('saveState').textContent=`已存入 Google Drive · ${new Date().toLocaleString('zh-TW')}`;renderList();toast('家庭資料與照片已儲存，並完成雲端讀回核對。');}catch(e){dirty=true;$('saveState').textContent='尚未完成儲存，請保留畫面並重試或下載完整備份';toast(e.message);}finally{setBusy(false);}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const safeName=()=> (current.name||'家庭照護').replace(/[<>:"/\\|?*]/g,'_');
async function toDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});}
async function backup(){if(!current||busy)return;setBusy(true);try{const data=structuredClone(current),originals={};for(const p of data.photos){$('saveState').textContent=`正在準備完整備份：${p.name}`;originals[p.id]=await toDataURL(await photoBlob(p));}download(new Blob([JSON.stringify({format:'lili-homecare-backup',version:1,exportedAt:new Date().toISOString(),family:data,originals})],{type:'application/json'}),`${safeName()}_完整備份_${new Date().toISOString().slice(0,10)}.json`);toast('完整備份已交給瀏覽器下載，包含文字與照片原檔。請確認下載完成。');}catch(e){toast(`備份未完成：${e.message}`);}finally{setBusy(false);$('saveState').textContent=dirty?'有修改尚未存入 Drive':remote?'家庭資料已存入 Drive':'草稿尚未存入 Drive';}}
async function restore(file){if(!file||busy||!allowLeave())return;setBusy(true);try{const b=JSON.parse(await file.text());if(b.format!=='lili-homecare-backup'||b.version!==1||!b.originals)throw Error('請選擇 App 下載的完整備份 JSON。');const f=validateFamily(b.family);if(typeof b.family.outputDraft==='string')f.outputDraft=b.family.outputDraft;const blobs=new Map();for(const p of f.photos){const data=b.originals[p.id];if(typeof data!=='string'||!data.startsWith(`data:${p.mime};base64,`))throw Error(`備份缺少照片原檔：${p.name}`);const base64=data.slice(data.indexOf(',')+1);const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));if(bytes.length!==p.size)throw Error('照片原檔大小與備份記錄不一致。');blobs.set(p.id,new Blob([bytes],{type:p.mime}));delete p.driveId;}
 f.id=crypto.randomUUID();f.name+= '（還原副本）';for(const [id,blob]of blobs)pending.set(id,blob);remote=null;families.push({id:f.id,name:f.name,data:f});openFamily(f);changed();toast('已還原成獨立草稿，原有家庭資料不會被覆蓋。請儲存到 Drive。');}catch(e){toast(`無法還原：${e.message}`);}finally{setBusy(false);$('restoreFile').value='';}}
$('newBtn').onclick=$('startBtn').onclick=()=>addFamily();$('demoBtn').onclick=()=>addFamily(true);$('search').oninput=renderList;$('familyList').onclick=e=>{const b=e.target.closest('[data-family]');if(b)selectFamily(b.dataset.family);};$('sectionNav').onclick=e=>{const a=e.target.closest('a');if(a){e.preventDefault();const d=$(a.hash.slice(1));d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'});}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(!busy)setTab(b.dataset.tab);});$('undoBtn').onclick=()=>{if(!history.length||busy)return;current=JSON.parse(history.pop());changed();render();};$('saveBtn').onclick=save;$('connectBtn').onclick=connect;$('settingsBtn').onclick=()=>{$('clientId').value=localStorage.getItem('liliOAuthClientId')||'';$('settings').showModal();};$('applySettings').onclick=()=>{const id=$('clientId').value.trim();if(!/^[a-zA-Z0-9-]+\.apps\.googleusercontent\.com$/.test(id)){toast('請填入有效的 Google OAuth 用戶端 ID。');return;}localStorage.setItem('liliOAuthClientId',id);$('settings').close();toast('連線設定已保存。請按「連接保姆 Google Drive」完成授權。');};$('photoFiles').onchange=e=>addPhotos([...e.target.files]);$('backupBtn').onclick=backup;$('restoreBtn').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=e=>restore(e.target.files[0]);$('closePhoto').onclick=()=>$('lightbox').close();$('lightbox').addEventListener('close',()=>{if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;$('fullPhoto').removeAttribute('src');});
$('output').oninput=()=>{capture();current.outputDraft=$('output').value;changed();};$('regenerateBtn').onclick=()=>{if(current.outputDraft!==undefined&&!confirm('重新產生會取代這裡手動調整的輸出文字，繼續嗎？'))return;capture();current.outputDraft=makeText(current);$('output').value=current.outputDraft;changed();};$('clearOutput').onclick=()=>{capture();current.outputDraft='';$('output').value='';changed();};$('copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);toast('已複製文字計畫書。');}catch{toast('無法自動複製，請在文字框內全選後複製。');}};$('downloadBtn').onclick=()=>download(new Blob([$ ('output').value],{type:'text/plain;charset=utf-8'}),`${safeName()}_照護計畫書.txt`);
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});renderList();
